181	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
182	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
183	  // interaction.
184	  useEffect(() => {
185	    const container = scrollContainerRef.current;
186	    if (!container || totalSlides <= 1) return undefined;
187	
188	    const handleScrollEnd = () => {
189	      const slideWidth = container.clientWidth || 1;
190	      const nearest = Math.round(container.scrollLeft / slideWidth);
191	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
192	    };
193	
194	    container.addEventListener('scrollend', handleScrollEnd);
195	    return () => container.removeEventListener('scrollend', handleScrollEnd);
