199	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
200	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
201	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
