203	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
204	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
205	
206	  return (
207	    <chakra.div __css={styles.root} data-card-slot="media">
208	      <chakra.div
209	        ref={scrollContainerRef}
210	        __css={styles.scrollContainer}
211	        data-testid="card-media-scroll"
212	        role={canNavigateByKeyboard ? 'group' : undefined}
213	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
214	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
215	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
