266	      {canPage && (
267	        <chakra.div __css={styles.carousel} data-card-slot="carousel">
268	          <chakra.button
269	            type="button"
270	            __css={styles.arrowButton}
271	            aria-label={intl.formatMessage(messages.previousImage)}
272	            onClick={() => goToRelativeSlide(-1)}
