/**
 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
 *
 * Every test below fires a click/keydown directly on the target control's own DOM node via
 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
 * screen position, in an actual browser, would land on that control rather than on the invisible
 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
 * the right `position`/`z-index` values (verified by literally compiling it through this
 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
 * to "a real browser click lands on the right element" is exactly the gap a real-browser
 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
 */
describe('ZimmProductCard — every interactive control stays separately clickable (wiring only, see limitation above)', () => {
  test('the bag button fires onAddToBag independently of the name-link overlay (PLP)', async () => {
    const onAddToBag = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} onAddToBag={onAddToBag} />);
    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
    expect(onAddToBag).toHaveBeenCalledTimes(1);
  });

  test('the carousel arrows fire independently of the name-link overlay when there is more than one image', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
    mockScrollTo();
    await user.click(screen.getByRole('button', { name: 'Next image' }));
    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
  });

  test('a size chip fires onSizeChipSelect independently of the name-link overlay (PLP)', async () => {
    const onSizeChipSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} sizeChipValues={SIZES} onSizeChipSelect={onSizeChipSelect} />);
    await user.click(screen.getByRole('radio', { name: 'S' }));
    expect(onSizeChipSelect).toHaveBeenCalledWith('s');
  });

  test('the remove (close) button fires onRemove independently of the name-link overlay (Wishlist)', async () => {
    const onRemove = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
    const button = screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' });
    await user.click(button);
    expect(onRemove).toHaveBeenCalledTimes(1);
  });

  test('the bag button also fires onAddToBag on a Wishlist card, independently of the remove button', async () => {
    const onAddToBag = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onAddToBag={onAddToBag} />);
    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
    expect(onAddToBag).toHaveBeenCalledTimes(1);
  });

  test('the name link itself is still a real, working anchor to href, not swallowed by its own overlay', () => {
    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
