/**
 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
 * zimmProductCardMedia/index.test.tsx's "Fix 1" block and
 * zimmProductCardContent/index.test.tsx's own real-recipe block. The component-level tests above
 * all render through the flat mock at the top of this file, which cannot see whether the real
 * recipe ever regresses the hover-reveal media query, the stretched-link overlay, or the z-index
 * lift on the interactive controls.
 *
 * These string keys were independently verified by compiling this exact recipe shape through
 * this project's own installed Stylis (v4.2.0 — the same engine Emotion/Chakra invoke at
 * runtime): the plain descendant selectors below resolve exactly as written, scoped under this
 * recipe's own generated class, with no comma-list scoping surprises.
 */
describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  const HOVER_CAPABLE_QUERY = '@media (hover: hover) and (pointer: fine)';
  const STRETCH_KEY = '[data-card-slot="content"] a::after';
  const CLOSE_LIFT_KEY = '[data-card-slot="close"]';
  const CAROUSEL_LIFT_KEY = '[data-card-slot="carousel"] button';
  const CONTENT_LIFT_KEY = '[data-card-slot="content"] button';
  const PRICE_KEY = '[data-card-slot="content"] [data-card-slot="price"]';
  const SIZE_CHIPS_KEY = '[data-card-slot="content"] [data-card-slot="sizeChips"]';
  const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
  const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;

  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const after = root[STRETCH_KEY] as Record<string, unknown>;
    expect(after.position).toBe('absolute');
    expect(after.inset).toBe(0);
    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
  });

  test('every interactive-control selector is lifted above the overlay with position:relative + zIndex:1', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    for (const key of [CLOSE_LIFT_KEY, CAROUSEL_LIFT_KEY, CONTENT_LIFT_KEY]) {
      const rule = root[key] as Record<string, unknown>;
      expect(rule.position).toBe('relative');
      expect(rule.zIndex).toBe(1);
    }
  });

  test('root itself establishes the positioned ancestor the stretched-link overlay resolves against', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    expect((style.root as Record<string, unknown>).position).toBe('relative');
  });

  test('home (hoverRevealsPrice): price is hidden by default and revealed only on hover, no size-selector rule at all', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverRevealsPrice: true });
    const root = style.root as Record<string, unknown>;
    expect((root[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
  });

  test('plp/wishlist (hoverHidesPrice + hoverRevealsSizeSelector): price visible by default, size-selector hidden by default, both swap on hover', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverHidesPrice: true, hoverRevealsSizeSelector: true });
    const root = style.root as Record<string, unknown>;
    // No unconditional price rule — Content's own natural rendering already shows it by default.
    expect(root[PRICE_KEY]).toBeUndefined();
    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
  });

  test('with every hover flag false/absent, no hover-reveal rule is emitted at all — a touch/no-hover pointer keeps the natural default permanently', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[PRICE_KEY]).toBeUndefined();
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
  });
});

/**
 * No `switch`/`if` on `props.variation` anywhere in this organism's render body (index.tsx) is
 * the extensibility AC's actual proof and is not practically assertable at runtime — a test could
 * only prove one execution path took/didn't take a branch, not that no such branch exists in the
